import React, { useState, useEffect, useMemo, useRef } from 'react'
import AdaptableCard from 'components/shared/AdaptableCard'
import DataTable from 'components/shared/DataTable'
import Tabs from 'components/ui/Tabs'
import debounce from 'lodash/debounce'
import Button from 'components/ui/Buttons'
import Input from 'components/ui/Input'
import toast from 'components/ui/toast'
import Notification from 'components/ui/Notification'
import { Link, useNavigate } from 'react-router-dom'
import { MdCreate, MdAdd, MdDelete, MdImportExport } from 'react-icons/md'
import { HiSearch } from 'react-icons/hi'
import { exportToExcel } from 'react-easy-export'
import NumberFormat from 'react-number-format'
import Tooltip from 'components/ui/Tooltip'
import { apiGRNGet } from 'services/GRNService'
import ViewGRN from './ViewGRN'

const { TabNav, TabList, TabContent } = Tabs

const GoodsReceivedNote = () => {
    const [data, setData] = useState([])
    const [loading, setLoading] = useState(true)
    const [selectedRows, setSelectedRows] = useState([])
    const [tableData, setTableData] = useState({
        total: 0,
        pageIndex: 1,
        pageSize: 10,
        query: '',
        sort: {
            order: '',
            key: '',
        },
        status: 'inProcess',
    })

    const [statusCount, setStatusCount] = useState({
        inProcess: 0,
        pending: 0,
        rejected: 0,
        inActive: 0,
        approved: 0,
    })

    const tabChanges = (tab) => {
        setTableData((prevData) => ({
            ...prevData,
            ...{ status: tab },
        }))
    }

    const navigate = useNavigate()
    const inputRef = useRef(null)

    const debounceFn = debounce(handleDebounceFn, 1000)

    function handleDebounceFn(val) {
        if (typeof val === 'string' && (val.length > 1 || val.length === 0)) {
            setTableData((prevData) => ({
                ...prevData,
                ...{ query: val, pageIndex: 1 },
            }))
        }
    }

    const handleChange = (e) => {
        debounceFn(e.target.value)
    }

    const handleRowClick = (dataid) => {
        // navigate(`/transaction/purchase-order/edit-purchase-order/${dataid}`);
        console.log(dataid)
    }

    const columns = useMemo(
        () => [
            {
                header: 'Date Of Receipt',
                accessorKey: 'date_of_receipt',
                cell: (props) => {
                    let a = new Date(props.row.original.date_of_receipt)
                    return `${
                        a.getDate() < 10 ? '0' + a.getDate() : a.getDate()
                    }-${
                        a.getMonth() + 1 < 10
                            ? '0' + (a.getMonth() + 1)
                            : a.getMonth() + 1
                    }-${a.getFullYear()}`
                },
                width: 100,
            },
            {
                header: 'PO No.',
                cell: (props) => {
                    return props.row.original.purchase_order === null ||
                        props.row.original.purchase_order === ''
                        ? ''
                        : props.row.original.purchase_order['po_no']
                },
                width: 180,
            },
            {
                header: 'Vendor Name',
                cell: (props) => {
                    return props.row.original.vendor === null ||
                        props.row.original.vendor === ''
                        ? ''
                        : props.row.original.vendor['vendor_name']
                },
            },
            {
                header: 'Depot Name',
                cell: (props) => {
                    return props.row.original.depot === null ||
                        props.row.original.depot === ''
                        ? ''
                        : props.row.original.depot['depot_name']
                },
            },
            {
                header: 'Amount',
                cell: (props) => {
                    return props.row.original.final_amount === null ||
                        props.row.original.final_amount === '' ? (
                        ''
                    ) : (
                        <NumberFormat
                            displayType="text"
                            prefix={'₹'}
                            thousandsGroupStyle={'lakh'}
                            decimalScale={2}
                            value={props.row.original.final_amount}
                            allowLeadingZeros
                            thousandSeparator=","
                        />
                    )
                },
                width: 100,
            },
            {
                header: 'Status',
                accessorKey: 'status',
                width: 90,
            },
            {
                header: 'Action',
                width: 110,
                cell: (props) => (
                    <>
                        <div
                            className={
                                props.row.original.status == 'Approved'
                                    ? 'hidden'
                                    : 'visible inline'
                            }
                        >
                            <Tooltip title="Edit GRN">
                                <Button
                                    shape="circle"
                                    size="sm"
                                    variant="twoTone"
                                    icon={<MdCreate />}
                                    className="text-sm mr-3"
                                    onClick={() => {
                                        navigate(
                                            `/transaction/goods-received-note/edit-goods-received-note/${props.row.original.id}`
                                        )
                                    }}
                                />
                            </Tooltip>
                        </div>
                        {/* <div className="hidden"> */}
                        <ViewGRN />
                        {/* </div> */}
                    </>
                ),
            },
        ],
        []
    )

    const handlePaginationChange = (pageIndex) => {
        setTableData((prevData) => ({ ...prevData, ...{ pageIndex } }))
    }

    const handleSelectChange = (pageSize) => {
        setTableData((prevData) => ({ ...prevData, ...{ pageSize } }))
    }

    const handleSort = ({ order, key }) => {
        setTableData((prevData) => ({
            ...prevData,
            ...{ sort: { order, key } },
        }))
    }

    const handleRowSelect = (checked, row) => {
        console.log('row', row)
        if (checked) {
            setSelectedRows((prevData) => {
                if (!prevData.includes(row)) {
                    return [...prevData, ...[row]]
                }
                return prevData
            })
        } else {
            setSelectedRows((prevData) => {
                if (prevData.includes(row)) {
                    return prevData.filter((prevRow) => prevRow.id !== row.id)
                }
                return prevData
            })
        }
    }

    const handleAllRowSelect = (checked, rows) => {
        console.log('rows', rows)
        if (checked) {
            const originalRows = rows.map((row) => row.original)
            const selectedIds = []
            originalRows.forEach((row) => {
                selectedIds.push(row)
            })
            setSelectedRows(selectedIds)
        } else {
            setSelectedRows([])
        }
    }

    console.log('PurchaseOrder.js Loading....')

    useEffect(() => {
        const fetchData = async () => {
            // setLoading(true)
            await apiGRNGet(tableData)
                .then((data) => {
                    console.log(data.data)
                    if (data.data) {
                        setStatusCount({
                            inProcess: data.data['statusCount'].inProcess,
                            pending: data.data['statusCount'].pending,
                            rejected: data.data['statusCount'].rejected,
                            inActive: data.data['statusCount'].inActive,
                            approved: data.data['statusCount'].approved,
                        })
                        setData(data.data['rows'])
                        setTableData((prevData) => ({
                            ...prevData,
                            ...{ total: data.data['total'] },
                        }))
                        setLoading(false)
                    }
                })
                .catch((error) => {
                    if (error.response.status === 500) {
                        console.log(error)
                        setLoading(false)
                    }
                })
            return true
        }
        fetchData()
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [
        tableData.pageIndex,
        tableData.sort,
        tableData.pageSize,
        tableData.query,
        tableData.status,
    ])
    return (
        <AdaptableCard className="card-shadow">
            <div className="lg:flex items-center justify-between mb-0">
                <h3 className="mb-4 lg:mb-0 ">GRN (Good Received Note)</h3>
                <div className="flex flex-row lg:flex-row lg:items-center">
                    <Input
                        ref={inputRef}
                        placeholder="Search..."
                        size="sm"
                        className="lg:w-52 mr-4"
                        onChange={handleChange}
                        prefix={<HiSearch className="text-lg" />}
                    />
                    <div className=" inline-flex">
                        <Button
                            size="sm"
                            variant="solid"
                            color="emerald-600"
                            icon={<MdImportExport />}
                            onClick={() => {
                                exportToExcel(selectedRows)
                            }}
                            disabled={!selectedRows.length > 0}
                        >
                            <span>Download</span>
                        </Button>
                    </div>
                </div>
            </div>

            <Tabs
                defaultValue="inProcess"
                onChange={(tabValue) => {
                    tabChanges(tabValue)
                }}
            >
                <TabList className="justify-end">
                    <TabNav value="inProcess">
                        Rate Pending {`(${statusCount.inProcess})`}
                    </TabNav>
                    <TabNav value="pending">
                        Pending Approved {`(${statusCount.pending})`}
                    </TabNav>
                    <TabNav value="rejected">
                        Rejected {`(${statusCount.rejected})`}
                    </TabNav>
                    <TabNav value="inActive">
                        Cancelled {`(${statusCount.inActive})`}
                    </TabNav>
                    <TabNav value="approved">
                        Approved {`(${statusCount.approved})`}
                    </TabNav>
                </TabList>
                <div className="p-1">
                    <TabContent value="inProcess"></TabContent>
                    <TabContent value="pending"></TabContent>
                    <TabContent value="rejected"></TabContent>
                    <TabContent value="inactive"></TabContent>
                    <TabContent value="approved"></TabContent>
                </div>
            </Tabs>
            <DataTable
                selectable
                columns={columns}
                data={data}
                loading={loading}
                pagingData={tableData}
                onPaginationChange={handlePaginationChange}
                onSelectChange={handleSelectChange}
                onSort={handleSort}
                onCheckBoxChange={handleRowSelect}
                onIndeterminateCheckBoxChange={handleAllRowSelect}
                columnShow={+false}
            />
        </AdaptableCard>
    )
}

export default GoodsReceivedNote
